def safe_compute(a, b):
    try:
        a = int(a)
        b = int(b)
        return str(a / b)
    except ValueError:
        return 'Invalid input: please enter integers only.'
    except ZeroDivisionError:
        return 'Cannot divide by zero.'
    except Exception:
        return 'An unexpected error occurred.'
